#!/usr/bin/env python3
"""Independent verification of (FR), Lemma M machine, B_c bound, stale-row claims.

Reads solver table output: line q (0-indexed) has f(q,0..rmax).
"""
import sys
from itertools import count

TAB = "scratch/table_300_700.txt"
f = []
for line in open(TAB):
    f.append([int(x) for x in line.split()])
QMAX = len(f) - 1
RMAX = len(f[0]) - 1
print(f"table q<={QMAX}, r<={RMAX}")

def F(x, r):
    """first-clause-extended f: F(x,r)=f(x,r) for x>=r else f(x,x)"""
    return f[x][r] if x >= r else f[x][x]

def mex_pos(S):
    """mex over positive integers"""
    S = set(S)
    m = 1
    while m in S:
        m += 1
    return m

def mex_nonneg(S):
    S = set(S)
    m = 0
    while m in S:
        m += 1
    return m

# ---------- sanity: cross-check recurrence of MISSION s2 against solver ----------
bad_rec = 0
for q in range(0, QMAX + 1):
    for r in range(0, min(q, RMAX) + 1):
        if r > q:
            exp = f[q][q]
        elif f[q - 1][r] < q:
            exp = f[q - 1][r]
        else:
            S = {F(x, r) for x in range(q)} | {f[q][b] for b in range(r)}
            exp = mex_pos(S)
        if exp != f[q][r]:
            bad_rec += 1
            if bad_rec < 5:
                print("REC MISMATCH", q, r, exp, f[q][r])
print("recurrence-vs-solver mismatches:", bad_rec)

# ---------- B_c bound: f(q,c) <= q + c + 1 ----------
bad_bound = 0
for q in range(0, QMAX + 1):
    for c in range(0, min(q, RMAX) + 1):
        if f[q][c] > q + c + 1:
            bad_bound += 1
print("bound f(q,c)<=q+c+1 violations:", bad_bound)

