#!/usr/bin/env python3
"""Part 2: claim test on census_50000.tsv exact tails (independently cross-validated
against raw solver f-values for r <= 300). Exhaustive r <= 2000, stride sample and
all anomaly rows (periods 6/8/9) neighborhoods up to r = 50000."""
import math, time

rows = []
for line in open("census_50000.tsv"):
    if line.startswith("#") or line.startswith("r\t"):
        continue
    fl = line.rstrip("\n").split("\t")
    rows.append((fl[1], int(fl[2]), int(fl[3]),
                 None if fl[4] == "-" else [int(x) for x in fl[4].split(",")]))
assert len(rows) == 50001

def tail(c, x):
    cls, per, N, dv = rows[c]
    u = N - c
    if x < u: return "PRE"
    if cls == "stale": return None
    return dv[(x - u) % per]

def check_row(r, a_list):
    cls_r, per_r, N_r, _ = rows[r]
    q_r = 1; mxN = 0
    for c in range(r):
        cls, per, N, _ = rows[c]
        p = 1 if cls == "stale" else per
        q_r = q_r * p // math.gcd(q_r, p)
        if N > mxN: mxN = N
    sigma = mxN - r
    start = max(sigma, 0)
    bad = []
    for a in a_list:
        v1 = set(); v2 = set(); leak = False
        for c in range(r):
            b1 = tail(c, a + r - c)
            b2 = tail(c, a + q_r + r - c)
            if b1 == "PRE" or b2 == "PRE":
                leak = True; break

