"""Referee counterexample hunt for the CLAIM:

  a -> V''(a) = U_{c<r} {B_c(a+r-c)} (defined values only)
  is q_r-periodic for all a >= max(sigma_r, 0),
  q_r = lcm{p_c : c<r}, sigma_r = max_{c<r} N(c) - r.

Part A: from solver table (raw f values), rows r=1..200, a up to 400-r.
Part B: from census_50000.tsv exact tails: r=1..3000 exhaustive,
        sampled + anomaly neighborhoods up to r=50000.
Part C: sharpness: value of V'' at a = max(sigma_r,0)-1 (does periodicity
        start earlier? is the threshold an overestimate?).
"""
import math

# ---------------- Part A: raw table ----------------
f = []
for line in open("scratch/ref_table_400.txt"):
    if line.startswith("#"):
        continue
    f.append([int(x) for x in line.split()])
QMAX = len(f) - 1

def row_profile(c):
    B = {}
    x = 0
    while c + x <= QMAX:
        q = c + x
        v = f[q][c] - q
        if v >= 0:
            B[x] = v
            x += 1
        else:
            break
    xmax = QMAX - c
    last = max(B) if B else -1
    stale = (last < xmax)
    if stale:
        return B, True, last + 1 + 1, 1, c + last + 1   # N = q0+1, u = N-c
    for cand in range(1, 61):
        for x0 in range(0, xmax - cand + 1):
            if all(B.get(x) == B.get(x + cand) for x in range(x0, xmax - cand + 1)):
                return B, False, c + x0, cand, x0
    return B, None, None, None, None

profiles = {c: row_profile(c) for c in range(0, QMAX + 1)}
badA = []
checkedA = 0
for r in range(1, 201):
    qs = 1
    mxN = None
    ok = True
    for c in range(r):
        B, st, N, p, u = profiles[c]
        if st is None:
            ok = False
            break
        pc = 1 if st else p
        qs = qs * pc // math.gcd(qs, pc)
        mxN = N if mxN is None else max(mxN, N)
    if not ok:
        continue
    sigma = mxN - r
    start = max(sigma, 0)
    amax = QMAX - r
    for a in range(start, amax + 1):
        v1 = set()
        v2 = set()
        if a + qs > amax:
            break
        leak = False
        for c in range(r):
            B, st, N, p, u = profiles[c]
            for (aa, out) in ((a, v1), (a + qs, v2)):
                x = aa + r - c
                if x > QMAX - c:
                    leak = True
                elif x in B:
                    out.add(B[x])
        if leak:
            break
        checkedA += 1
        if v1 != v2:
            badA.append((r, a, sorted(v1), sorted(v2), qs, sigma))
            break
print("PART A (table): rows with full profiles r<=200; pairs (r,a) checked=%d, failures=%d"
      % (checkedA, len(badA)))
for t in badA[:10]:
    print("   FAIL", t)

# ---------------- Part B: census tails ----------------
rows = []
for line in open("census_50000.tsv"):
    if line.startswith("#") or line.startswith("r\t"):
        continue
    fl = line.rstrip("\n").split("\t")
    rows.append((fl[1], int(fl[2]), int(fl[3]),
                 None if fl[4] == "-" else [int(x) for x in fl[4].split(",")]))
assert len(rows) == 50001

def tail(c, x):
    cls, per, N, dv = rows[c]
    u = N - c
    if x < u:
        return "PRE"
    if cls == "stale":
        return None
    return dv[(x - u) % per]

# cross-validate census tails against raw solver table for c <= 300
mism = 0
for c in range(0, min(300, QMAX) + 1):
    cls, per, N, dv = rows[c]
    u = N - c
    for x in range(0, QMAX - c + 1):
        q = c + x
        v = f[q][c] - q
        t = tail(c, x)
        if t == "PRE":
            exp = v if v >= 0 else None
            if exp != (v if v >= 0 else None):
                pass
            # PRE region: compare directly
            if v >= 0:
                continue
            mism += 1
            print("census PRE but table undefined", c, x)
            continue
        if cls == "stale":
            exp = None if v < 0 else v
            if exp is not None and x >= u:
                mism += 1
                print("stale tail says undefined but table has", c, x, v)
        else:
            if v != t and x >= u:
                mism += 1
                if mism < 5:
                    print("census tail mismatch", c, x, t, v)
print("census-tail vs solver-table mismatches (c<=300):", mism)

def check_row(r, a_list, window):
    cls_r, per_r, N_r, _ = rows[r]
    q_r = 1
    mxN = 0
    for c in range(r):
        cls, per, N, dv = rows[c]
        p = 1 if cls == "stale" else per
        q_r = q_r * p // math.gcd(q_r, p)
        if N > mxN:
            mxN = N
    sigma = mxN - r
    start = max(sigma, 0)
    out = []
    for a in a_list:
        v1 = set(); v2 = set(); leak = False
        for c in range(r):
            b1 = tail(c, a + r - c)
            b2 = tail(c, a + q_r + r - c)
            if b1 == "PRE" or b2 == "PRE":
                leak = True
                break
            if b1 is not None:
                v1.add(b1)
            if b2 is not None:
                v2.add(b2)
        if leak:
            out.append((a, "LEAK", None))
            continue
        out.append((a, v1 == v2, (sorted(v1), sorted(v2))))
    return q_r, sigma, start, out

badB = []
checkedB = 0
leaks = 0
target_rows = list(range(1, 3001))
# anomaly neighborhoods + sample up to 50000
extra = []
for r in range(3001, 50001):
    cls, per, N, dv = rows[r]
    if per not in (0, 1, 2, 3, 4, 9):
        extra.append(r)
    elif r % 37 == 0:
        extra.append(r)
target_rows += extra
print("PART B: rows checked = %d (exhaustive <=3000 + %d sampled/anomaly rows)" % (len(target_rows), len(extra)))

for r in target_rows:
    q_r, sigma, start, _ = check_row(r, [], 0)
    a_list = [start + i for i in range(0, min(3 * q_r + 3, 60))]
    q_r, sigma, start, res = check_row(r, a_list, 0)
    for (a, ok, det) in res:
        if ok == "LEAK":
            leaks += 1
            badB.append((r, a, "PRE-leak", None))
            break
        checkedB += 1
        if not ok:
            badB.append((r, a, det[0], det[1]))
            break
print("PART B: (r,a) pairs checked=%d, failures=%d, PRE-leaks=%d" % (checkedB, len(badB), leaks))
for t in badB[:10]:
    print("   FAIL", t)

# ---------------- Part C: sharpness below the threshold ----------------
fail_below = 0
tested_below = 0
for r in target_rows[:3000]:
    q_r, sigma, start, _ = check_row(r, [], 0)
    if start == 0:
        continue
    q_r, sigma, start, res = check_row(r, [start - 1], 0)
    for (a, ok, det) in res:
        if ok == "LEAK":
            continue
        tested_below += 1
        if not ok:
            fail_below += 1
print("PART C: at a = max(sigma_r,0)-1: tested=%d, periodicity FAILS at %d (threshold is sharp/near-sharp)"
      % (tested_below, fail_below))
